test("US-02 development plan sync preserves documents and stops on editor changes", async () => {
  const fixture = await mkdtemp(join(tmpdir(), "quote-plan-sync-"));
  const secret = () => randomBytes(32).toString("hex");
  Object.assign(process.env, {
    DATABASE_FILENAME: join(fixture, "strapi.sqlite"),
    STRAPI_TELEMETRY_DISABLED: "true",
    APP_KEYS: [secret(), secret()].join(","),
    ADMIN_JWT_SECRET: secret(),
    API_TOKEN_SALT: secret(),
    JWT_SECRET: secret(),
    TRANSFER_TOKEN_SALT: secret(),
    ENCRYPTION_KEY: secret(),
  });

  const context = await compileStrapi({ appDir: resolve(".") });
  const app = createStrapi(context);
  try {
    await app.load();
    const { syncDevPlans, PLAN_EXPANSION_KEY } = require("../dist/src/dev-plan-sync.js");
    const plans = app.documents("api::quote-content.plan");
    const store = app.store({ type: "core", name: "quote-content" });
    const fixtureBenefits = [{ text: "Asistencia en carretera" }];
    const legacy = (await plans.findMany({ status: "draft" })).filter(({ name }) => name !== "Integral");
    const initial = await syncDevPlans(app);
    assert.equal(initial.status, "noop", "fresh seed already includes all plans");
    assert.equal(Object.keys(await store.get({ key: PLAN_EXPANSION_KEY })).length, 2);
    for (const { documentId, name } of await plans.findMany({ status: "draft" })) {
      if (name === "Integral") await plans.delete({ documentId });
      else await plans.update({ documentId, status: "published", data: { benefits: fixtureBenefits } });
    }
    await store.delete({ key: PLAN_EXPANSION_KEY });

    const unrelated = await plans.create({
      data: {
        country: "co", name: "Plan adicional de prueba", shortDescription: "Sin publicar",
        basePrice: 10000, currency: "COP", active: false, recommended: false, order: 90,
      },
      status: "draft",
    });
    const admin = await app.service("admin::user").create({
      firstname: "Test", lastname: "Fixture", email: "catalog-sync@example.test",
      password: secret(), isActive: true,
    });
    const draftFields = (documentId) => plans.findOne({ documentId, status: "draft", populate: ["benefits"] });
    const publishedFields = (documentId) => plans.findOne({ documentId, status: "published", populate: ["benefits"] });
    const originalCo = legacy.find(({ country, name }) => country === "co" && name === "Esencial");
    const ready = await syncDevPlans(app);
    assert.equal(ready.status, "ready");
    assert.equal(ready.actions.filter(({ kind }) => kind === "update").length, 4);
    assert.equal(ready.actions.filter(({ kind }) => kind === "create").length, 2);
    assert.equal((await publishedFields(originalCo.documentId)).benefits.length, 1, "dry run does not write");

    await plans.update({ documentId: originalCo.documentId, status: "draft", data: { shortDescription: "Cambio editorial" } });
    assert.equal((await syncDevPlans(app, ready.fingerprint)).status, "blocked");
    assert.equal((await draftFields(originalCo.documentId)).shortDescription, "Cambio editorial");
    for (const document of legacy) assert.equal((await publishedFields(document.documentId)).benefits.length, 1);
    assert.equal((await plans.findMany({ filters: { name: "Integral" }, status: "draft" })).length, 0);
    await plans.discardDraft({ documentId: originalCo.documentId });

    assert.equal((await syncDevPlans(app, "0".repeat(64))).status, "stale");
    const verified = await syncDevPlans(app);
    assert.equal((await syncDevPlans(app, verified.fingerprint)).status, "applied");
    for (const document of legacy) {
      const draft = await draftFields(document.documentId);
      const published = await publishedFields(document.documentId);
      assert.equal(draft.name, document.name);
      assert.equal(published.basePrice, document.basePrice);
      assert.ok(draft.benefits.length > 1);
      assert.deepEqual(draft.benefits.map(({text}) => text), published.benefits.map(({text}) => text));
    }
    assert.equal((await draftFields(unrelated.documentId)).name, unrelated.name);
    assert.equal(await publishedFields(unrelated.documentId), null);
    assert.equal((await app.db.query("admin::user").findOne({ where: { id: admin.id } })).email, admin.email);
    const noOp = await syncDevPlans(app);
    assert.equal(noOp.status, "noop");
    assert.equal((await syncDevPlans(app, noOp.fingerprint)).status, "noop");
    assert.equal((await plans.findMany({ filters: { name: "Integral" }, status: "draft" })).length, 2);

    const { co, cl } = await store.get({ key: PLAN_EXPANSION_KEY });
    await plans.unpublish({ documentId: co });
    await plans.delete({ documentId: cl });
    assert.equal((await syncDevPlans(app)).status, "blocked");
    assert.equal(await publishedFields(co), null);
    assert.equal(await draftFields(cl), null);
  } finally {
    await app.destroy();
    await rm(fixture, { recursive: true, force: true });
  }
});
EOF
