      visibility: style.visibility,
      opacity: style.opacity,
      forcedColorAdjust: style.forcedColorAdjust,
    };
  });
  expect(radioStyle.appearance).not.toBe("none");
  expect(radioStyle.visibility).toBe("visible");
  }
